package com.allinone.supply.controller;
import com.allinone.common.annotation.RepeatSubmit; import com.allinone.common.core.controller.BaseController; import com.allinone.common.core.domain.AjaxResult; import com.allinone.supply.domain.Invoice; import com.allinone.supply.service.IInvoiceService; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/supply/invoices") public class InvoiceRegistrationController extends BaseController { @Autowired private IInvoiceService service; @PreAuthorize("@ss.hasPermi('supply:invoice:add')") @RepeatSubmit @PostMapping public AjaxResult add(@RequestBody Invoice invoice){service.createDraft(invoice); return success(invoice);} @PreAuthorize("@ss.hasPermi('supply:invoice:edit')") @PutMapping public AjaxResult edit(@RequestBody Invoice invoice){return toAjax(service.updateDraft(invoice));} @PreAuthorize("@ss.hasPermi('supply:invoice:edit')") @RepeatSubmit @PostMapping("/confirm") public AjaxResult confirm(@RequestBody Invoice invoice){return toAjax(service.confirm(invoice));} @PreAuthorize("@ss.hasPermi('supply:invoice:edit')") @RepeatSubmit @PostMapping("/submit") public AjaxResult submit(@RequestBody Invoice invoice){return toAjax(service.submit(invoice));} }
